import ast

def score(program: str) -> float:
    try:
        n = sum(1 for _ in ast.walk(ast.parse(program)))
        return min(1.0, n / 100.0)
    except:
        return 0.0

def score(program: str) -> float:
    try:
        import ast
        ast.parse(program)
    except:
        return 0.5

    ifs = program.count('if ')
    fors = program.count('for ')
    defs = program.count('def ')

    complexity = ifs + fors * 1.5 + defs * 2
    return min(1.0, complexity / 8.0)

